display.text:
// #53 Part B (approved 2026-09-17: proposals/approved/
// 2026-09-17_agent-feedback-closedown.md — "approved both parts in one
// unit"; Part A, the mandatory close-down prompt step, already landed in
// the role prompts): the `submit` custom tool — ONE unified append tool for
// the three agent-inbox channels. The #53 problem: the maintainer-only
// `agent_feedback.md` friction log was OPTIONAL and the early-close-at-
// stop-line discipline discarded optional close-down steps, so friction
// observations were systematically lost — AND the entry had to be hand-
// formatted (date_time + role tag) and hand-appended (file fiddling,
// accidental reads). This tool removes the hand-formatting AND the file
// fiddling: the agent supplies the text only; the tool machine-stamps each
// entry (date + role + session) and appends it.
//
// Behavior (append-only — the tool NEVER reads or rewrites a target):
//   1. args: `feedback?` / `knowledge?` / `todo?` / `ideas?` / `memory?`
//      (all optional strings, at least one required — an EMPTY string
//      counts as NOT provided).
//      role + session for the stamp are AUTO-FILLED from the tool context
//      (role = context.agent else `agent`; session = context.sessionID
//      else `unknown`) — there is NO role/session parameter;
//   2. NONE provided -> return an error string, no file touched;
//   3. for each PROVIDED param, append ONE entry to its HARDCODED target
//      (relative to `context.directory ?? process.cwd()`): entry =
//      `<header> <YYYY-MM-DD_HH-MM> <role> <session>` + the raw text + one
//      trailing blank line;
//        feedback  -> agent/agent_feedback.md       (### header)
//        knowledge -> agent/knowledge/knowledge_inbox.md (## header)
//        todo      -> todo_inbox.md (repo root)               (## header)
//        ideas     -> agent/agent_ideas.md          (### header)
//        memory    -> agent/memory/<role>/memory_inbox.md (### header)
//                    (2026-09-29 approved proposal 2026-09-28_submit-
//                    memory-channel.md: a FIFTH, ROLE-SCOPED channel —
//                    <role> = the context.agent id BEFORE the first `_`
//                    (`planner_Q3S_245K_slow` -> `planner`), fallback
//                    `agent` when the context carries no agent. Distinct
//                    from `knowledge` (repo-general fact -> the shared
//                    knowledge inbox) and `ideas` (maintainer-side
//                    stream, read-only for agents): `memory` = verified
//                    role-scoped experience/procedure for THIS role's
//                    memory inbox; the curation lane (memory README
//                    write policy) cures inbox entries into the role's
//                    memory.md + destilled_mem.md. The inbox FILE and its
//                    role FOLDER are created when not already existing
//                    (his ruling 3 — supersedes the proposal's file-only
//                    recommendation).)
//      the header depth is the established form of each channel (the
//      feedback file is maintainer-curated with ### entries; the two inbox
//      files use ##; agent_ideas.md follows the feedback ### form); a
//      missing target file (or its parent dir) is CREATED carrying only the
//      entry — no header invention;
//   4. return, per provided param: `<param>` + `target: <relative path>` +
//      `entry: <exact text>` (blocks in
//      feedback/knowledge/todo/ideas/memory order).
//
// Sandbox discipline: the targets are HARDCODED — there is NO path
// parameter (that is the sandbox). NOTE the deliberate deviation from the
// proposal's ".opencode/ subtree" wording: `todo_inbox.md` sits at the
// repo root (the AGENTS.md Discovery contract file) — the spec
// (handover_task.md, 2026-09-18) ratifies the three exact paths.
//
// The host names the tool by FILENAME — no `name` field (the committed
// tool() form, cf. loop_log.ts / ctx_gauge.ts / block_transfer.ts).
// Registration is the maintainer's domain (the live opencode.jsonc + the
// per-agent tool-access grant — this file is deliberately NOT registered
// in any repo config).
import { appendFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { tool } from "@opencode-ai/plugin";

// Local clock, `YYYY-MM-DD_HH-MM` (minute resolution) — the SAME stamp form
// the existing inbox/feedback entries use. Machine-computed; NEVER retyped
// or compared by eye (AGENTS.md pattern 5).
function localStamp(d: Date = new Date()): string {
  const p = (n: number) => String(n).padStart(2, "0");
  return (
    `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}` +
    `_${p(d.getHours())}-${p(d.getMinutes())}`
  );
}

// The three HARDCODED channel targets (relative to the project dir) + their
// established header depths. There is NO path parameter — this table IS the
// sandbox.
const CHANNELS = {
  feedback: { rel: "agent/agent_feedback.md", header: "###" },
  knowledge: { rel: "agent/knowledge/knowledge_inbox.md", header: "##" },
  todo: { rel: "todo_inbox.md", header: "##" },
  ideas: { rel: "agent/agent_ideas.md", header: "###" },
} as const;
type ChannelKey = keyof typeof CHANNELS;

export default tool({
  description: `Appends ONE machine-stamped entry (<header> <YYYY-MM-DD_HH-MM> <role> <session> + your raw text) to each of the provided inbox channels — feedback (friction points: what slowed/confused this session, one line preferred) -> agent/agent_feedback.md; knowledge (verified, actionable knowledge in inbox format) -> agent/knowledge/knowledge_inbox.md; todo (a loose finding, unnumbered — the planner assigns IDs at curation) -> todo_inbox.md; ideas (what is missing or could be done differently to improve something generally — process, toolset, general function, design, interaction of parts; NOT friction, that is feedback) -> agent/agent_ideas.md (the agent-side ideas inbox; the maintainer's own ideas.md is his personal stream, not this target); memory (verified, role-scoped experience/procedure/lesson that improves THIS role's future work — NOT repo-general facts, those go to knowledge) -> agent/memory/<role>/memory_inbox.md, where <role> = your agent id before the first '_' (the maintainer's curation lane cures inbox entries into the role's memory.md + destilled_mem.md). Memory-entry guideline (enough to make a valid, reliable memory — full format in agent/memory/README.md, design intent in agent/knowledge/plugin_tools/2026-09-18_tool-plugin-design-handout.md): write ONE concise, self-contained memory statement plus, where known: its type (observed/derived/decided/learned/preference/hypothesis), confidence (high/medium/low), scope (when it applies), an evidence/source locator (file, commit, log line, incident), and a review trigger. NO transient session detail, NO speculation presented as fact, NO restatement of prompt/AGENTS.md/knowledge text (memory is a curated knowledge base, not a diary — search before assuming it is new). Fire it with at least one of feedback/knowledge/todo/ideas/memory (several at once allowed; pass an empty string for the ones you skip). The date is stamped automatically and role + session are auto-filled from the tool context (role =... (line truncated to 2000 chars)
  args: {
    feedback: tool.schema
      .string()
      .optional()
      .describe("Friction description (one line preferred): what slowed down or confused this session, an unclear rule, missing context, a caught near-miss."),
    knowledge: tool.schema
      .string()
      .optional()
      .describe("Verified, actionable knowledge for the knowledge inbox (dated + role-tagged by the stamp; the knowledge curator moves it to the area files)."),
    todo: tool.schema
      .string()
      .optional()
      .describe("A loose finding (unnumbered) for the planner's TODO curation: problem + evidence, desired outcome, acceptance criteria."),
    ideas: tool.schema
      .string()
      .optional()
      .describe("An improvement idea for the agent-side ideas inbox: what is missing or could be done differently to improve something generally (process, toolset, general function, design, interaction of parts). Not friction — friction goes to feedback."),
    memory: tool.schema
      .string()
      .optional()
      .describe("Verified, role-scoped memory for THIS role's own memory inbox (agent/memory/<role>/memory_inbox.md — <role> = the agent id before the first '_'): one concise, self-contained memory statement plus type (observed/derived/decided/learned/preference/hypothesis), confidence, scope, an evidence/source locator, and a review trigger — NO transient session detail, NO speculation as fact, NO restatement of prompt/AGENTS.md/knowledge text. Repo-general facts go to knowledge instead."),
  },

  execute: async (args: any, context: any) => {
    const dir = context?.directory ?? process.cwd();

    // An empty/blank string counts as NOT provided (the same convention as
    // loop_log's session handling).
    // The memory channel's target is ROLE-SCOPED (the context.agent prefix
    // before the first '_'), so it is resolved outside the hardcoded
    // CHANNELS table; the other four channels are unchanged.
    const provided = (Object.keys(CHANNELS) as ChannelKey[]).filter(
      (k) => args[k] != null && String(args[k]).trim() !== ""
    );
    const memoryProvided = args["memory"] != null && String(args["memory"]).trim() !== "";
    if (provided.length === 0 && !memoryProvided) {
      return "error: none of feedback/knowledge/todo/ideas/memory provided — nothing written";
    }

    const stamp = localStamp();
    // role + session are AUTO-FILLED from the tool context — the agent never
    // supplies them (the empty/blank string counts as NOT provided, the same
    // convention as loop_log's session handling).
    const role =
      context?.agent != null && String(context.agent).trim() !== "" ? String(context.agent) : "agent";
    const session =
      context?.sessionID != null && String(context.sessionID).trim() !== "" ? String(context.sessionID) : "unknown";
    // <role> = the agent id BEFORE the first '_' (`planner_Q3S_245K_slow` ->
    // `planner`; an id without '_' keeps itself; the fallback role `agent`
    // maps to the `agent` namespace).
    const rolePrefix = role.split("_")[0];

    const blocks: string[] = [];
    for (const key of provided) {
      const { rel, header } = CHANNELS[key];
      const target = path.join(dir, rel);
      mkdirSync(path.dirname(target), { recursive: true }); // missing dir -> create (recursive)
      const entry = `${header} ${stamp} ${role} ${session}\n${String(args[key])}\n\n`;
      appendFileSync(target, entry, "utf-8"); // append-only: the target is NEVER read
      blocks.push(`${key}\ntarget: ${rel}\nentry: ${entry}`);
    }
    if (memoryProvided) {
      const rel = `agent/memory/${rolePrefix}/memory_inbox.md`;
      const target = path.join(dir, rel);
      // His ruling 3: the inbox FILE and its role FOLDER are created when
      // not already existing (recursive mkdir = both).
      mkdirSync(path.dirname(target), { recursive: true });
      const entry = `### ${stamp} ${role} ${session}\n${String(args["memory"])}\n\n`;
      appendFileSync(target, entry, "utf-8"); // append-only: the target is NEVER read
      blocks.push(`${"memory"}\ntarget: ${rel}\nentry: ${entry}`);
    }
    return blocks.join("\n");
  }
});

