// file is deliberately NOT registered in any repo config).
import { tool } from "@opencode-ai/plugin"
import { readGauge, formatGauge } from "../plugin/scripts/gauge.mjs"

export default tool({
  description: `Reads the context usage of the current (or a named) session, read-only.
Returns the \`SESSION=… CTX=… (…%) REM=…\` readout (window unknown → no pct/REM; no total / unreadable db → CTX=notAvailable with the error appended). The readout line ends with the distinct \` | N compactions left\` budget suffix when the budget store resolves (file absent / unparseable → no suffix). Fire this for context-budget decisions instead of the peek.mjs shell-out.
The readout LAGS true usage by ≈1 tool call (~5k tokens — the in-flight step's output, not yet in the DB; the gauge reads the last FINISHED step's in+out+cr, #103) — treat it as a LOWER bound and plan with margin (the same lag applies to the injected ctx: nudge lines).`,
  args: {
    sessionID: tool.schema.string().optional().describe("Session id to read (the per-session read). Empty/omitted: the newest-updated session (the default peek read)."),
  },

  execute: async (args: any, context: any) => {
    // The shared core read (NEVER throws — a hard failure comes back as
    // kind:"db-error" with the capped, backend-naming error text).
    const r = await readGauge(undefined, args?.sessionID);
    let out = formatGauge(r);
    if (r.kind === "db-error") out += ` — ${r.error}`; // the in-band mirror of peek.mjs's stderr note
    return out;
  }
});

